declare s clob;n number;begin if user<>'RABAEV'or sys_context('USERENV','SERVICE_NAME')<>'orcl'then raise_application_error(-20999,'WRONG_TARGET');end if;select count(*)into n from USER_OBJECTS where OBJECT_NAME in('RRL_CASE_MANUAL_TARE','RRL_CASE_MANUAL_TARE_API');if n<>0 then raise_application_error(-20999,'MANUAL_TARE_OBJECT_EXISTS');end if;
s:=null;dbms_lob.createtemporary(s,true);for r in(select TEXT from USER_SOURCE where NAME='RRL_CASE_SCALE_ADMISSION'and TYPE='PACKAGE BODY'order by LINE)loop dbms_lob.append(s,replace(r.TEXT,chr(13),''));end loop;if rawtohex(sys.dbms_crypto.hash(rtrim(s,chr(10)),sys.dbms_crypto.hash_sh256))<>'5E39D9B3BEE0E8E1EF28DFDE1260B5802A65ECA173733248B2032DB43983D487'then raise_application_error(-20999,'SOURCE_DRIFT');end if;dbms_lob.freetemporary(s);
s:=null;dbms_lob.createtemporary(s,true);for r in(select TEXT from USER_SOURCE where NAME='RRL_WH_FINAL_SCALE_ADMISSION'and TYPE='PACKAGE BODY'order by LINE)loop dbms_lob.append(s,replace(r.TEXT,chr(13),''));end loop;if rawtohex(sys.dbms_crypto.hash(rtrim(s,chr(10)),sys.dbms_crypto.hash_sh256))<>'4A65E3F7A1FAE5372E0CDB5DEB14356ED9BAA6F22CD95B42F364CD975013824A'then raise_application_error(-20999,'SOURCE_DRIFT');end if;dbms_lob.freetemporary(s);
end;
